**Implementation example:**

```javascript
const SearchBox = connectSearchBox(({refine}) => {
  const [readValue, writeValue] = useState(emptyStr)
  const handleChange = ({currentTarget: {value}}: EventInput) => writeValue(value)
  const handleSubmit = () => readValue !== emptyStr && refine(readValue)
  const handleClear = () => {
    writeValue(emptyStr)
    refine(emptyStr)
  }
  return (
    <>
      <label htmlFor='search-input'>Search</label>
      <input id='search-input' type='search' value={readValue} onChange={handleChange} />
      <button onClick={handleSubmit}>Search</button>
      <button onClick={handleClear}>Clear</button>
    </>
```
